/// <summary>
/// DebuC 16.10.23
/// </summary>
public class NDXUmsSalesGroupMember extends common
{
}

Method.Source:
/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "accountNum">CustAccount</param>
/// <param name = "salesGroup">CommissSalesGroup</param>
/// <param name = "firma">NDXCompanys</param>
/// <returns>boolean</returns>
static boolean existsAccountInSalesGroup(CustAccount           accountNum,
                              CommissSalesGroup     salesGroup,
                              NDXCompanys             firma)
{
    return ((select recId
            from        NDXUmsSalesGroupMember
                where   NDXUmsSalesGroupMember.SalesGroup  == salesGroup
                    &&  NDXUmsSalesGroupMember.AccountNum  == accountNum
                    &&  NDXUmsSalesGroupMember.Company       == firma
         ).RecId > 0);
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
static void fill()
{
    CustTable                   custTableComp, custTable;
    NDXUmsSalesGroupMember      nDX_UmsSalesGroupMember, nDX_UmsSalesGroupMemberGrp;

    container                   conComp;
    NDXUmsatzClass             ndxUmsClass;
    NDXUmsatzClassArgs         args = new NDXUmsatzClassArgs();
    int                         i;
    CompanyId                   company;
    NDXCompanys                 firma;
    RecordInsertList            rilUmsSalesGroupMember;
    ;
    info(strfmt("@NDX:NDXDeterminationCustomerPerCompanySalesGrp", NDXHelperCommon::seconds2Str()));       // [%1] Start: Ermittlung der Debitoren je UK je Verkaufsgruppe (Prov.)
    args.parmlGetLastValues(NDXNoYesBE::No);
    ndxUmsClass = NDXUmsatzClass::construct(args);
    conComp = ndxUmsClass.parmConCompanies();       // umsatzbeteiligte UK's

    delete_from nDX_UmsSalesGroupMember;

    // über alle Provisionsgruppen aller Debitoren aller Umsatz-UK's
    while select crosscompany:conComp custTableComp
    group by custTableComp.SalesGroup
    {
        // Abarbeitung der Umsatz-UK's dieser Provisionsgruppe
        for (i = 1; i <= conlen(conComp); i++)
        {
            company = conpeek(conComp, i);
            firma   = NDXHelperCommon::CompanyId2NDXCompany(company, false);
            changecompany(company)
            {
                rilUmsSalesGroupMember = new RecordInsertList(tableNum(NDXUmsSalesGroupMember));
                custTable = null;
                while select    custTable
                where       custTable.SalesGroup == custTableComp.SalesGroup
                {
                    ttsbegin;
                    nDX_UmsSalesGroupMember.CompanyId   = company;
                    nDX_UmsSalesGroupMember.SalesGroup  = custTableComp.SalesGroup;
                    nDX_UmsSalesGroupMember.Party       = custTable.Party;
                    nDX_UmsSalesGroupMember.AccountNum  = custTable.AccountNum;
                    nDX_UmsSalesGroupMember.Company     = firma;
                    rilUmsSalesGroupMember.add(nDX_UmsSalesGroupMember);
                    ttscommit;
                }
                rilUmsSalesGroupMember.insertDatabase();
            }
        }
    }

    // Prüfung der Debitoren, die unterschiedliche Kontonummern haben
    setprefix("@NDX:NDXDebitorsWithDiffentAccountingNumbers");
    while select        nDX_UmsSalesGroupMemberGrp
        group by    AccountNum, Party
        exists join nDX_UmsSalesGroupMember
            where   nDX_UmsSalesGroupMember.SalesGroup  == nDX_UmsSalesGroupMemberGrp.SalesGroup
                &&  nDX_UmsSalesGroupMember.AccountNum  != nDX_UmsSalesGroupMemberGrp.AccountNum
                &&  nDX_UmsSalesGroupMember.Party       == nDX_UmsSalesGroupMemberGrp.Party
    {
        //info(strfmt('AccountNum [%1], PartyId [%2], CompanyId [%3], SalesGroup [%4]',nDX_UmsSalesGroupMemberGrp.AccountNum, nDX_UmsSalesGroupMemberGrp.PartyId ));
        info(strfmt('AccountNum [%1], PartyId [%2]',nDX_UmsSalesGroupMemberGrp.AccountNum, nDX_UmsSalesGroupMemberGrp.Party ));
    }


    // Prüfung: Existieren Datensätze mit gleichen Kontonummern und unterschiedlichen PartyId's
    setprefix("@NDX:NDXDebitorsWithDifferentGlobalAddresses");
    while select nDX_UmsSalesGroupMemberGrp
        group by    AccountNum, Party
        exists join nDX_UmsSalesGroupMember
            where   nDX_UmsSalesGroupMember.SalesGroup  == nDX_UmsSalesGroupMemberGrp.SalesGroup
                &&  nDX_UmsSalesGroupMember.AccountNum  == nDX_UmsSalesGroupMemberGrp.AccountNum
                &&  nDX_UmsSalesGroupMember.Party       != nDX_UmsSalesGroupMemberGrp.Party
    {
        //info(strfmt('AccountNum [%1], PartyId [%2], CompanyId [%3], SalesGroup [%4]',nDX_UmsSalesGroupMemberGrp.AccountNum, nDX_UmsSalesGroupMemberGrp.PartyId ));
        info(strfmt('AccountNum [%1], PartyId [%2]',nDX_UmsSalesGroupMemberGrp.AccountNum, nDX_UmsSalesGroupMemberGrp.Party ));
    }

    info(strfmt("@NDX:NDXDeterminationCustomerPerCompanySalesGrpEnd", NDXHelperCommon::seconds2Str()));    // [%1] Ende: Ermittlung der Debitoren je UK je Verkaufsgruppe (Prov.)
}
